class Solution {
    private List<List<Integer>> graph;
    private int[] state;
    private int[] order;
    private int write;

    public int[] findOrder(int numCourses, int[][] prerequisites) {
        graph = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) {
            graph.add(new ArrayList<>());
        }
        for (int[] prerequisite : prerequisites) {
            graph.get(prerequisite[1]).add(prerequisite[0]);
        }

        state = new int[numCourses];
        order = new int[numCourses];
        write = numCourses - 1;
        for (int course = 0; course < numCourses; course++) {
            if (!dfs(course)) {
                return new int[0];
            }
        }
        return order;
    }

    private boolean dfs(int course) {
        if (state[course] == 1) {
            return false;
        }
        if (state[course] == 2) {
            return true;
        }

        state[course] = 1;
        for (int next : graph.get(course)) {
            if (!dfs(next)) {
                return false;
            }
        }
        state[course] = 2;
        order[write--] = course;
        return true;
    }
}

import java.util.*;

class Solution {
    public int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> prereqGraph = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) {
            prereqGraph.add(new ArrayList<>());
        }
        for (int[] prerequisite : prerequisites) {
            int course = prerequisite[0];
            int before = prerequisite[1];
            prereqGraph.get(course).add(before);
        }

        int[] state = new int[numCourses];
        List<Integer> order = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) {
            if (!visit(course, prereqGraph, state, order)) {
                return new int[0];
            }
        }

        int[] result = new int[numCourses];
        for (int i = 0; i < numCourses; i++) {
            result[i] = order.get(i);
        }
        return result;
    }

    private boolean visit(int course, List<List<Integer>> prereqGraph, int[] state, List<Integer> order) {
        if (state[course] == 1) {
            return false;
        }
        if (state[course] == 2) {
            return true;
        }

        state[course] = 1;
        for (int before : prereqGraph.get(course)) {
            if (!visit(before, prereqGraph, state, order)) {
                return false;
            }
        }
        state[course] = 2;
        order.add(course);
        return true;
    }
}

import java.util.*;

class Solution {
    public int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) {
            graph.add(new ArrayList<>());
        }
        for (int[] prerequisite : prerequisites) {
            graph.get(prerequisite[1]).add(prerequisite[0]);
        }

        int[] state = new int[numCourses];
        int[] order = new int[numCourses];
        int write = numCourses - 1;

        for (int start = 0; start < numCourses; start++) {
            if (state[start] != 0) {
                continue;
            }
            Deque<int[]> stack = new ArrayDeque<>();
            stack.push(new int[]{start, 0});
            while (!stack.isEmpty()) {
                int[] frame = stack.peek();
                int course = frame[0];
                if (state[course] == 0) {
                    state[course] = 1;
                }

                if (frame[1] == graph.get(course).size()) {
                    state[course] = 2;
                    order[write--] = course;
                    stack.pop();
                    continue;
                }

                int next = graph.get(course).get(frame[1]);
                frame[1]++;
                if (state[next] == 1) {
                    return new int[0];
                }
                if (state[next] == 0) {
                    stack.push(new int[]{next, 0});
                }
            }
        }

        return order;
    }
}
